-- Lot T4 des Tarides (03/11/2026) : annexes A11 à A46 des Tarides (primes, contrats, défis, reliques ; brouillon
-- des Tarides, §4.1.2 à 4.1.6). Généré par outils\annexes_durotar.py tarides (données : annexes_tarides.py) :
-- ne pas modifier à la main. Scripts : v3_annexes.cpp (tables de la migration 143).
USE acore_world;
SET SESSION sql_mode = '';

-- Tables de retour : créatures, apparitions, puissances et objets du monde modifiés en place.
CREATE TABLE solazeroth_v3_t4_origine_creatures SELECT entry, AIName, ScriptName, npcflag FROM creature_template WHERE entry IN (3292, 3389, 3415, 3449, 3472, 3474, 5864, 9316, 910060);
CREATE TABLE solazeroth_v3_t4_origine_apparitions SELECT guid, spawntimesecs FROM creature WHERE map = 1 AND id IN (3470, 3270, 3394, 5830, 3452, 5864, 5841, 5838, 5828, 5859, 5851, 3253, 3474, 3473, 5834, 5832, 3472, 5827);
CREATE TABLE solazeroth_v3_t4_origine_puissances SELECT * FROM solazeroth_v3_puissance_entrees WHERE entree IN (3470, 3270, 3394, 5830, 3452, 5864, 5841, 5838, 5828, 5859, 5851, 3253, 3474, 3473, 5834, 5832, 3472, 5827);
CREATE TABLE solazeroth_v3_t4_origine_objets_monde SELECT entry, Data1, ScriptName FROM gameobject_template WHERE entry IN (3685, 4072, 6906, 6907, 6908, 61935, 61936, 161752);

