INSERT INTO quest_template (ID, QuestType, QuestLevel, MinLevel, QuestSortID, RewardMoney, Flags, LogTitle, LogDescription, QuestDescription, QuestCompletionLog, RewardItem1, RewardAmount1, RequiredNpcOrGo1, RequiredNpcOrGoCount1) VALUES (910241, 2, -1, 0, 17, 14000, 0, 'Le garde du Refuge', 'Tue Rathorian, à la porte du Refuge de Brume-funeste.', 'Sarilus avait un garde du corps, qui n''était pas de la Lame. Il garde encore la porte du Refuge. Sa Frappe mortelle coupe les soins. Frappe vite, avant que ta potion ne manque.', 'Retourne voir qui t''a confié cette tâche.', 910801, 1, 3470, 1);
INSERT INTO quest_template_addon (ID, PrevQuestID, SpecialFlags) VALUES (910241, 910048, 0);
INSERT INTO quest_request_items (ID, EmoteOnComplete, EmoteOnIncomplete, CompletionText) VALUES (910241, 1, 1, 'Rathorian garde toujours la porte ?');
INSERT INTO quest_offer_reward (ID, Emote1, RewardText) VALUES (910241, 1, 'Le garde est tombé. Prends cette cape : elle était à lui. 15 Marques du voyageur. Rangé dans ta Collection : 17 éclats cadavériques.');
