INSERT INTO quest_template (ID, QuestType, QuestLevel, MinLevel, QuestSortID, RewardMoney, Flags, LogTitle, LogDescription, QuestDescription, QuestCompletionLog, RequiredNpcOrGo1, RequiredNpcOrGoCount1) VALUES (910242, 2, -1, 0, 17, 14000, 0, 'L''ancienne mystique', 'Tue l''Ancienne mystique Tranchegroin, sur le versant est de la Colline des épines.', 'AVIS DE RECHERCHE. L''Ancienne mystique Tranchegroin soigne les Tranchecrins de la colline. Elle plante un totem guérisseur : brisez-le. Sa vague de soins se coupe, mais rien n''oblige à la couper.', 'Retourne voir qui t''a confié cette tâche.', 3270, 1);
INSERT INTO quest_template_addon (ID, PrevQuestID, SpecialFlags) VALUES (910242, 0, 0);
INSERT INTO quest_request_items (ID, EmoteOnComplete, EmoteOnIncomplete, CompletionText) VALUES (910242, 1, 1, 'La mystique soigne toujours les siens.');
INSERT INTO quest_offer_reward (ID, Emote1, RewardText) VALUES (910242, 1, 'La mystique est morte. Voici la prime. 15 Marques du voyageur. Rangé dans ta Collection : 17 éclats cadavériques, des composants.');
