INSERT INTO quest_template (ID, QuestType, QuestLevel, MinLevel, QuestSortID, RewardMoney, Flags, LogTitle, LogDescription, QuestDescription, QuestCompletionLog, RequiredNpcOrGo1, RequiredNpcOrGoCount1) VALUES (910243, 2, -1, 0, 17, 18500, 0, 'Le chef des Kolkar', 'Tue Barak Plaie-des-kodos, au nord des Bassins oubliés.', 'Barak Plaie-des-kodos mène les Kolkar du nord. Il jette son filet, puis tire de loin. Colle-le dès que le filet tombe. Quand il faiblit, ses Légions-tempête accourent.', 'Retourne voir qui t''a confié cette tâche.', 3394, 1);
INSERT INTO quest_template_addon (ID, PrevQuestID, SpecialFlags) VALUES (910243, 910053, 0);
INSERT INTO quest_request_items (ID, EmoteOnComplete, EmoteOnIncomplete, CompletionText) VALUES (910243, 1, 1, 'Barak vit encore ?');
INSERT INTO quest_offer_reward (ID, Emote1, RewardText) VALUES (910243, 1, 'Barak est mort. Les Kolkar du nord n''ont plus de chef. 20 Marques du voyageur. Rangé dans ta Collection : 23 éclats cadavériques, des composants.');
