INSERT INTO quest_template (ID, QuestType, QuestLevel, MinLevel, QuestSortID, RewardMoney, Flags, LogTitle, LogDescription, QuestDescription, QuestCompletionLog, RewardItem1, RewardAmount1, RequiredNpcOrGo1, RequiredNpcOrGoCount1, RequiredNpcOrGo2, RequiredNpcOrGoCount2) VALUES (910244, 2, -1, 0, 17, 35500, 0, 'Les sœurs du ciel', 'Tue Sœur Rathtalon et Serena Plumesang, dans les Collines arides.', 'Deux harpies règnent sur les aires des Ensorçaile. Leur vent repousse au bord des aires, et leurs tueuses viennent quand elles faiblissent. Garde le dos au rocher.', 'Retourne voir qui t''a confié cette tâche.', 910802, 1, 5830, 1, 3452, 1);
