INSERT INTO quest_template (ID, QuestType, QuestLevel, MinLevel, QuestSortID, RewardMoney, Flags, LogTitle, LogDescription, QuestDescription, QuestCompletionLog, RequiredNpcOrGo1, RequiredNpcOrGoCount1) VALUES (910245, 2, -1, 0, 17, 35500, 0, 'Le Peau-piquante', 'Tue Peau-piquante Pourcegart, au nord d''Agama''gor.', 'AVIS DE RECHERCHE. Pourcegart a la peau couverte de piquants : chaque coup porté au contact blesse celui qui frappe. Quand il faiblit, il fonce et assomme.', 'Retourne voir qui t''a confié cette tâche.', 5864, 1);
