INSERT INTO quest_template (ID, QuestType, QuestLevel, MinLevel, QuestSortID, RewardMoney, Flags, LogTitle, LogDescription, QuestDescription, QuestCompletionLog, RequiredNpcOrGo1, RequiredNpcOrGoCount1) VALUES (910259, 2, -1, 0, 17, 22000, 0, 'Le sable qui grouille', 'Tue le Moissonneur silithide sans potion, pendant que le sable grouille.', 'Le Moissonneur garde la ruche. Pendant le combat, une larve sort du sable sous tes pieds toutes les dix secondes : tue-la dès qu''elle sort. Et pas de potion.', 'Retourne voir qui t''a confié cette tâche.', 3253, 1);
