INSERT INTO quest_template (ID, QuestType, QuestLevel, MinLevel, QuestSortID, RewardMoney, Flags, LogTitle, LogDescription, QuestDescription, QuestCompletionLog, RequiredNpcOrGo1, RequiredNpcOrGoCount1) VALUES (910260, 2, -1, 0, 17, 44000, 0, 'Bael''dun en douze minutes', 'Contre la montre : les 43 nains de Bael''dun puis Doublenattes renforcé. Bronze 12 min, argent 10 min, or 8 min.', 'Le donjon le plus dense des Tarides. Le chrono part au premier nain tué : vide Bael''dun et tue Doublenattes renforcé en moins de douze minutes. En moins de huit, cette cotte est à toi.', 'Retourne voir qui t''a confié cette tâche.', 910065, 1);
