INSERT INTO quest_offer_reward (ID, Emote1, RewardText) VALUES (910260, 1, 'Bael''dun est vidé. Reviens battre ton temps. 20 Marques du voyageur. Rangé dans ta Collection : 55 éclats cadavériques. Médaille d''argent : récompenses ×1,5 ; d''or : ×2.');
